let terrainRadius=12,terrainLevel=2,terrainUndo=[],terrainStampTime=0;
function terrainPoint(e){if(!view.getTile(e.clientX,e.clientY))return null;return {x:view.point.x,z:view.point.z};}
function terrainStamp(p){terrainStampTime=performance.now();const result=sculptTerrain(session.world,{...p,mode:toolOptions.terrain,radius:terrainRadius,target:terrainLevel},groundHeight);if(!result.ok){$('toolHint').textContent=result.reason;return false;}
 for(const c of result.undo.changes){const previous=drag.terrainChanges.get(c.i);if(previous)previous.after=c.after;else drag.terrainChanges.set(c.i,{...c});}
 for(const g of result.undo.grounds){const previous=drag.terrainGrounds.get(g.i);if(previous)previous.after=g.after;else drag.terrainGrounds.set(g.i,{...g});}
 drag.terrainCost+=result.cost;const b=result.bounds,prior=drag.terrainBounds;drag.terrainBounds=prior?{minX:Math.min(prior.minX,b.minX),maxX:Math.max(prior.maxX,b.maxX),minZ:Math.min(prior.minZ,b.minZ),maxZ:Math.max(prior.maxZ,b.maxZ)}:{...b};view.terrainChanged(b);$('toolHint').textContent='Earthworks · '+money(drag.terrainCost)+' this stroke';$('money').textContent=money(session.world.money);terrainStampTime=performance.now();return true;}
function finishTerrain(){if(!drag?.terrain)return;const stroke={changes:[...drag.terrainChanges.values()],grounds:[...drag.terrainGrounds.values()],cost:drag.terrainCost,bounds:drag.terrainBounds};drag=null;if(stroke.changes.length){terrainUndo.push(stroke);if(terrainUndo.length>20)terrainUndo.shift();view.terrainChanged(stroke.bounds,true);update();}view.clearLine();}
function terrainControls(){const row=document.createElement('div');row.id='terrainControls';row.className='terrain-controls';row.innerHTML='<label>Brush radius <select aria-label="Terrain brush radius"><option value="6">30 m</option><option value="12">60 m</option><option value="20">100 m</option></select></label><label>Level height <input aria-label="Terrain level height in metres" type="number" min="-25" max="250" step="5" style="width:70px"> m</label><button type="button">Undo terrain stroke</button>';
 const select=row.querySelector('select'),input=row.querySelector('input');select.value=String(terrainRadius);input.value=String(terrainLevel*5);select.onchange=()=>terrainRadius=Number(select.value);input.onchange=()=>{terrainLevel=Math.max(-25,Math.min(250,Number(input.value)||0));terrainLevel/=5;input.value=String(terrainLevel*5);};row.querySelector('button').onclick=()=>{const result=undoTerrain(session.world,terrainUndo.at(-1));if(!result.ok){toast(result.reason);return;}const stroke=terrainUndo.pop();view.terrainChanged(stroke.bounds,true);update();toast('Terrain stroke undone');};$('buildPanel').insertBefore(row,$('buildPanel').querySelector('.build-settings'));}
