for(const [cat,types]of Object.entries(categoryTypes)){categories[cat].items=Object.entries(E.BUILDINGS).filter(([,b])=>types.includes(b.type)).map(([building,b])=>[b.type,b.name,b.cost,E.TOOLS[b.type].icon,{building,density:['cottage','townhouse','shops'].includes(building)?'low':'high'}]);if(cat!=='zones')categories[cat].desc='Connect to a road. Each facility has its own capacity and daily upkeep.';}
