function transitControls(){ $('transitControls')?.remove();const row=document.createElement('div');row.id='transitControls';row.className='transit-controls';const summary=document.createElement('div');summary.id='transitStatus';row.append(summary);const buttons=document.createElement('div');buttons.className='road-modes';const finish=document.createElement('button');finish.textContent='Finish bus line';finish.onclick=finishBusLine;const clear=document.createElement('button');clear.textContent='Clear planned stops';clear.onclick=()=>{busStops=[];view.clearLine();$('toolHint').textContent='Choose 2–12 road stops, then Finish bus line';};const depots=document.createElement('button');depots.textContent='Depot tools';depots.onclick=()=>selectTool('bus',{building:'bus'},'Bus depot');buttons.append(finish,clear,depots);row.append(buttons);const list=document.createElement('div');list.className='transit-lines';for(const line of session.world.transit?.lines||[]){const item=document.createElement('div'),label=document.createElement('span'),remove=document.createElement('button');label.dataset.busLine=String(line.id);label.textContent=line.name+' · '+line.stops.length+' stops · '+line.completed+' completed rides';remove.textContent='Remove '+line.name;remove.onclick=()=>{session.world.transit.lines=session.world.transit.lines.filter(l=>l.id!==line.id);view.setupCars();transitControls();update();};item.append(label,remove);list.append(item);}row.append(list);$('buildPanel').insertBefore(row,$('buildPanel').querySelector('.build-settings'));updateTransitStatus();}
function updateTransitStatus(){const el=$('transitStatus');if(!el)return;for(const label of document.querySelectorAll('[data-bus-line]')){const line=session.world.transit?.lines.find(l=>l.id===Number(label.dataset.busLine));if(line)label.textContent=line.name+' · '+line.stops.length+' stops · '+line.completed+' completed rides';}const t=view.transit?.summary;el.textContent=t?t.lines+(t.lines===1?' line · ':' lines · ')+t.buses+(t.buses===1?' bus · ':' buses · ')+t.waiting+' waiting · '+t.riding+' riding · '+t.completed+' completed rides':'No bus lines yet';const blocked=[...(view.transit?.entries.values()||[])].filter(e=>e.reason);if(blocked.length)el.textContent+=' · '+blocked.map(e=>e.line.name+': '+e.reason).join(' · ');}
let zoneMode='rectangle';
