function commitRoad(controls){const r=tool==='path'?E.buildWalkPath(session.world,controls):E.buildRoadPath(session.world,controls,toolOptions.roadType||'street');if(!r.ok)toast(r.reason,true);else toast((tool==='path'?'Path':'Road')+' built · '+money(r.cost));cancelRoad();$('toolHint').textContent=roadMode==='curve'?'Click start, then bend, then end':'Drag from start to end';update()}
let store,storageBlocked=false;try{store=new E.WorldStore(localStorage)}catch(err){storageBlocked=true;store=new E.WorldStore({getItem:()=>null,setItem:()=>{throw Error('Existing storage is unreadable. Export the data before recovering it.')}});setTimeout(()=>toast(err.message,true),1000)}
const session=new E.GameSession(store);let view,tool='inspect',toolOptions={},category=null,brush=1,drag=null,painted=new Set(),lastAttempt=Date.now(),selectedId=store.currentId||store.worlds[0]?.id,saveFailed=false,toastTimer,photo=false,pausedBeforeMenu=false,externallyChanged=false;
