function demoWorld(){const w=E.createWorld('Borough','river',321);const street=(x,y,wide=false)=>{const t=w.tiles[y*48+x];if(t.ground==='land'){t.type='road';t.tree=false;t.roadWidth=wide?2:1}};for(let y of [12,18,24,30,36])for(let x=0;x<32;x++)street(x,y,y===24);for(let x of [8,14,20,26,31])for(let y=9;y<39;y++)street(x,y,x===20);for(let y=10;y<38;y++)for(let x=6;x<31;x++){const t=w.tiles[y*48+x],h=(x*17+y*31)%13;if(t.ground==='water'||t.type||h===0)continue;if(E.neighbors(y*48+x).some(i=>w.tiles[i].type==='road')||(x>=20&&x<=29&&y>=16&&y<=29)){const downtown=x>=21&&x<=29&&y>=16&&y<=29;t.type=h===4?'park':downtown?(h%3===0?'commercial':'office'):(x+y)%7===0?'commercial':'residential';t.density=x>14&&y<30&&h%3!==0?'high':'low';t.level=downtown?1+(x*y)%5:t.density==='high'?2+(x+y)%3:1;t.people=t.type==='residential'?t.level*6:0;t.tree=false;const choices=Object.entries(E.BUILDINGS).filter(([,b])=>b.type===t.type);if(choices.length)t.building=choices[(x+y)%choices.length][0];if(t.type==='residential')t.building=t.density==='low'?'cottage':(x+y)%2?'apartments':'tower';if(t.type==='commercial')t.density=downtown?'high':'low'}}return w}

const demo=demoWorld();
function toast(message,error=false){if(!message)return;$('toast').textContent=message;$('toast').classList.add('show');$('toast').classList.toggle('error',error);clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),error?9000:4500)}
function timestamp(time){return time?new Date(time).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'Not saved'}
function save(auto=false){if(!session.world||session.screen!=='game')return true;lastAttempt=Date.now();if(externallyChanged){toast('This world was saved in another tab. Export this session or reload before saving.',true);return false}try{session.save();saveFailed=false;$('saveState').classList.remove('error');updateSaveText();$('menuSaveStatus').textContent='Verified save · '+timestamp(session.world.savedAt);if(!auto)toast('Save verified · '+timestamp(session.world.savedAt));return true}catch(err){saveFailed=true;$('saveState').classList.add('error');$('saveState').textContent='Save failed · Export backup';$('menuSaveStatus').textContent='Save failed. Your city is still open; export a backup.';toast(err.message+' — your city remains open. Export a backup.',true);return false}}
function updateSaveText(){if(saveFailed||!session.world)return;const remaining=Math.max(0,Math.ceil((E.AUTOSAVE_MS-(Date.now()-(session.world.savedAt||Date.now())))/1000));$('saveState').textContent='Saved '+new Date(session.world.savedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+' · Auto '+Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');$('saveState').title='Last verified save: '+timestamp(session.world.savedAt)+' · Stored in this browser';}
function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close())}
function renderHome(){document.body.classList.add('at-home');document.body.classList.remove('game-build','photo-mode');$('homeScreen').hidden=false;$('gameUI').hidden=true;$('photoHint').hidden=true;photo=false;view.setBuild(false);view.cursor.visible=false;view.clearLine();view.setOverlay('none');view.setWorld(demo,{menu:true});view.setNight(false);const recent=store.get(store.currentId)||store.get(store.worlds[0]?.id);$('continue').disabled=!recent;$('continueMeta').textContent=recent?recent.name+' · '+E.analyze(recent).population.toLocaleString()+' residents\nLast saved '+timestamp(recent.savedAt):'Start a new game to create your first city.';selectedId=recent?.id||null;}
function start(id){if(session.screen==='game'&&!save(true))return;try{session.start(id)}catch(e){toast(e.message,true);return}externallyChanged=false;selectedId=id;saveFailed=false;category=null;terrainUndo=[];tool='inspect';toolOptions={};$('buildPanel').hidden=true;$('inspector').hidden=true;closeDialogs();document.body.classList.remove('at-home','game-build');$('homeScreen').hidden=true;$('gameUI').hidden=false;$('infoPanel').hidden=false;view.setWorld(session.world);view.setOverlay('none');view.setNight(false);save(true);update();toast('Welcome to '+session.world.name+'. Your city is now running.')}
function exitHome(){if(!save())return;session.screen='home';session.paused=true;view.running=false;closeDialogs();renderHome();toast('City saved. Continue or Load game to return.')}
function rank(pop){return pop>=2000?['City',5,5000]:pop>=1000?['Large Town',4,2000]:pop>=500?['Busy Town',3,1000]:pop>=300?['Big Village',2,500]:['Small Village',1,300]}

let residentsPage=0;
function residentAddress(i){return i===null?'Unassigned':(i%48)+', '+Math.floor(i/48);}
function showResidents(){const sim=view.residents;if(!sim)return;const summary=sim.summary;$('residentsSummary').textContent=summary.population+' residents · '+summary.households+' households · '+summary.employed+' jobs assigned · '+summary.travelling+' travelling';const rows=sim.state.residents,pages=Math.max(1,Math.ceil(rows.length/12));residentsPage=Math.min(residentsPage,pages-1);$('residentsList').replaceChildren();for(const r of rows.slice(residentsPage*12,residentsPage*12+12)){const row=document.createElement('div');row.style.cssText='padding:10px 0;border-bottom:1px solid #ffffff18;display:flex;gap:12px;align-items:center';const text=document.createElement('div');text.style.flex='1';text.textContent=sim.name(r)+' · '+r.activity+' | Home '+residentAddress(r.home)+' · Work '+residentAddress(r.work)+' · Work visits '+r.workdays+' · Shopping visits '+r.shopping;const button=document.createElement('button');button.textContent='Locate';button.onclick=()=>{const a=sim.agents.get(r.id),i=r.location,x=r.walk?.x??r.transit?.x??(a?.active?a.x:(i%48+.5)*4-96),z=r.walk?.z??r.transit?.z??(a?.active?a.z:(Math.floor(i/48)+.5)*4-96);view.controls.target.set(x,1,z);view.camera.position.set(x-12,14,z+18);view.controls.update();$('residentsDialog').close();update();};row.append(text,button);$('residentsList').append(row);}if(!rows.length)$('residentsList').textContent='No residents yet. Connect housing to roads, power and water so households can move in.';$('residentsPage').textContent=(residentsPage+1)+' / '+pages;$('residentsPrev').disabled=residentsPage===0;$('residentsNext').disabled=residentsPage>=pages-1;}
$('showResidents').onclick=()=>{showResidents();$('residentsDialog').showModal();view.running=false;};$('residentsPrev').onclick=()=>{residentsPage--;showResidents();};$('residentsNext').onclick=()=>{residentsPage++;showResidents();};
$('showOutside').onclick=()=>view.focusOutside();
$('trafficPolicy').onchange=()=>{if(!session.world)return;session.world.trafficPolicy=$('trafficPolicy').value;view.roadworks.updateSignals(view.traffic);update();};
function update(){if(!session.world)return;updateTransitStatus();const flow=view.traffic?.summary;$('trafficStatus').textContent=flow?flow.junctions+' controlled intersections · '+flow.queued+' queued vehicles · '+Math.min(100,Math.round(flow.averageSpeed/5*100))+'% traffic flow':'';$('trafficPolicy').value=session.world.trafficPolicy||'signals';const citizens=view.residents?.summary;$('residentStatus').textContent=citizens?citizens.households+' households · '+citizens.employed+' employed · '+citizens.travelling+' travelling':'';const traffic=view.traffic;$('outsideStatus').textContent=traffic?.portals.length?traffic.portals.length+' outside connections · '+traffic.trips.length+' reachable destinations · '+traffic.completed+' completed trips':'No outside connection. Extend a road to the map edge.';$('showOutside').disabled=!traffic?.portals.length;const w=session.world,a=E.analyze(w),r=rank(a.population);$('worldName').textContent=w.name;$('overviewName').textContent=w.name;$('milestone').textContent=r[0];$('overviewRank').textContent=r[0];$('rank').textContent=r[0].toUpperCase();$('cityLevel').textContent=r[1];$('overviewLevel').textContent=String(r[1]).padStart(2,'0');$('progress').style.width=Math.min(100,a.population/r[2]*100)+'%';$('progressLabel').textContent='Next milestone: '+r[2].toLocaleString()+' residents';$('population').textContent=a.population.toLocaleString();$('money').textContent=money(w.money);$('income').textContent=(a.income>=0?'+':'−')+money(Math.abs(a.income))+' / day';$('income').classList.toggle('negative',a.income<0);$('happiness').textContent=Math.round(a.happiness)+'%';$('happinessFace').textContent=a.happiness>60?'☺':a.happiness>35?'◉':'☹';$('date').textContent='Day '+w.day;$('pause').textContent=session.paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',session.paused?'Resume simulation':'Pause simulation');for(let n of [1,2,4])$('speed'+n).classList.toggle('active',session.speed===n);$('demandBars').innerHTML=[...a.demand,a.demand[2]*.7].map((v,i)=>`<i style="width:${v*.8}px" title="${['Residential','Commercial','Industrial','Office'][i]} demand: ${Math.round(v)}%"></i>`).join('');
const services=[['ϟ','Electricity',Math.ceil(a.utilityNeed)+' / '+a.power,a.power>=a.utilityNeed&&a.power>0],['◉','Water',Math.ceil(a.utilityNeed)+' / '+a.water,a.water>=a.utilityNeed&&a.water>0],['▤','Assigned jobs',String(view.residents?.summary.employed||0),true],['⇄','Active road trips',String(view.traffic?.active||0),true],['♧','Pollution',Math.round(a.pollution)+'%',a.pollution<25]];$('services').innerHTML=services.map(([icon,name,value,good])=>`<div class="service-row"><span class="service-icon">${icon}</span><span class="service-name">${name}</span><b class="${good?'good':'warn'}">${value}</b></div>`).join('');
$('advice').textContent=a.power===0?'Start with roads, a power station and a water tower. Place buildings beside roads connected to the map edge.':a.water===0?'Water is essential. Place a water tower beside a connected road.':a.population===0?'Your utilities are ready. Paint residential zones beside roads and watch your first neighborhood grow.':a.power<a.utilityNeed?'Power demand exceeds capacity. Build another power station.':a.water<a.utilityNeed?'Water demand exceeds capacity. Add another water tower.':a.jobs<a.population*.4?'Residents need jobs. Paint commercial, industrial or office zones.':a.income<0?'Spending exceeds tax income. Grow your city, or adjust your taxes in Economy.':'Your city is growing. Add parks and services to improve residents’ lives.';view.running=!session.paused&&!document.querySelector('dialog[open]');view.simSpeed=session.speed;view.refresh();updateSaveText();if($('budgetDialog').open)budgetDetails();}
let facilityHover=null;
function isFacility(){return !!E.FACILITY_DEFAULTS[tool];}
function facilityHint(){const id=toolOptions.building||E.FACILITY_DEFAULTS[tool],size=E.FACILITY_SITES[id];if(size)$('toolHint').textContent=E.BUILDINGS[id].name+' · '+size[0]*20+' × '+size[1]*20+' m · '+money(E.BUILDINGS[id].cost)+' · Click to place · R rotates';}
