function selectTool(id,options={},name){facilityHover=null;cancelRoad();$('buildPanel').classList.toggle('planning-transit',!!options.transit);tool=id;toolOptions={...options};$('roadControls').hidden=!['road','path'].includes(id);$('toolHint').textContent=(name||E.TOOLS[id]?.name||id)+(id==='road'?' · Click and drag · '+money(E.ROADS[options.roadType]?.cost||50)+' / tile · Bridges '+money((E.ROADS[options.roadType]?.cost||50)*4):id==='inspect'?' · Click to inspect':id==='bulldoze'?' · ₡10 · Curved roads are removed as a whole':' · Click or drag · '+money(E.BUILDINGS[options.building]?.cost||E.TOOLS[id]?.cost||0)+' / tile');if(isFacility())facilityHint();view.setZoning(!!options.zone);if(options.path)$('toolHint').textContent='Pedestrian path · '+(roadMode==='curve'?'Click start, bend, then end':'Drag from start to end')+' · ₡20 / 20 m';if(options.transit)$('toolHint').textContent='Click 2–12 road stops, then Finish bus line · '+busStops.length+' planned';if(options.terrain)$('toolHint').textContent='Drag to sculpt · Radius '+terrainRadius*5+' m · Foundations protected';if(options.zone)$('toolHint').textContent=(name||'Zoning')+' · Free · Drag an area · Buildings develop automatically';view.setBuild(id!=='inspect'&&$('gridSetting').checked);$('bulldoze').classList.toggle('active',id==='bulldoze');}
function showCategory(id){if(id===category&&!$('buildPanel').hidden){closeBuild();return}category=id;$('terrainControls')?.remove();$('transitControls')?.remove();$('buildPanel').classList.toggle('terrain-panel',id==='terrain');const c=categories[id];$('buildTitle').textContent=c.title.toUpperCase();$('toolDescription').textContent=c.desc;$('buildOptions').replaceChildren();$('brushControls').hidden=id!=='zones'||zoneMode!=='brush';$('roadControls').hidden=id!=='roads';$('zoneControls').hidden=id!=='zones';document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===id));c.items.forEach(([type,name,cost,icon,options],i)=>{const b=document.createElement('button');b.className='build-option';if(options.zone){b.classList.add('zone-option');b.style.setProperty('--zone-color',E.ZONES[options.zone]?.color||'#c9b7a1')}b.innerHTML=`<span class="model-icon">${icon}</span><strong>${name}</strong><small>${options.zone?'Free zoning':options.terrain?'Pay for soil moved':options.transit?'₡500 bus + ₡100 / stop':cost===null?'Information overlay':money(cost)}${options.building?(id==='zones'?' · Zone beside roads':' · '+E.BUILDINGS[options.building].capacity+'× capacity · '+money(E.BUILDINGS[options.building].upkeep)+'/day'):options.roadType?' · '+E.ROADS[options.roadType].lanes+' lanes · '+E.ROADS[options.roadType].speed+' km/h':''}</small>`;b.onclick=()=>{document.querySelectorAll('.build-option').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(id==='overlays'){selectTool('inspect');view.setOverlay(type)}else{view.setOverlay('none');selectTool(type,options,name)}};$('buildOptions').append(b);if(i===0&&id!=='overlays')b.click()});if(id==='terrain')terrainControls();if(id==='transport')transitControls();$('buildPanel').hidden=false;document.body.classList.add('game-build')}
