function inspect(p){const w=session.world,index=E.facilityOwner(w,p.y*48+p.x),t=w.tiles[index],a=E.analyze(w),connected=a.active.includes(index);$('inspector').hidden=false;const wrap=$('inspectContent');wrap.replaceChildren();let h=document.createElement('h3');h.textContent=!t.type&&t.zone?E.ZONES[t.zone].name:t.type?(E.BUILDINGS[t.building]?.name||E.ROADS[t.roadType]?.name||E.TOOLS[t.type].name):t.ground==='water'?'River & water':'Undeveloped land';wrap.append(h);const rows=t.type?[['Development level',t.level||'Zoned · Awaiting development'],['Residents',t.people||0],['Road access',t.type==='road'?(a.roads.has(p.y*48+p.x)?'Connected':'Isolated'):connected?'Connected':'Needs connection'],['Upkeep',money(E.building(t).upkeep||0)+' / day'],['District',p.x<24?'West Borough':'East Borough']]:[['Location',p.x+', '+p.y],['Suitable for',t.ground==='water'?'Bridges':'Roads, zoning & services']];if(t.facilitySite)rows.push(['Site',t.facilitySite.width*20+' × '+t.facilitySite.depth*20+' m'],['Demolition','Removes the entire facility']);if(t.zone)rows.push(['Zoning',E.ZONES[t.zone].name],['Development',E.developmentStatus(w,p.y*48+p.x)]);if(view.residents&&['residential','commercial','industrial','office'].includes(t.type)){const members=view.residents.state.residents.filter(r=>t.type==='residential'?r.home===p.y*48+p.x:r.work===p.y*48+p.x);rows.push([t.type==='residential'?'Residents living here':'Assigned workers',members.length]);for(const r of members.slice(0,6))rows.push([view.residents.name(r),r.activity]);}for(let [k,v]of rows){let line=document.createElement('div');line.textContent=k+': '+v;wrap.append(line)}}
function paint(p){if(!p)return;if(tool==='inspect'){inspect(p);return}if(toolOptions.zone){const cells=[];for(let y=p.y;y<p.y+brush;y++)for(let x=p.x;x<p.x+brush;x++)cells.push({x,y});applyZone(cells);return}for(let y=p.y;y<p.y+(category==='zones'?brush:1);y++)for(let x=p.x;x<p.x+(category==='zones'?brush:1);x++){const k=x+','+y;if(painted.has(k))continue;painted.add(k);const r=E.place(session.world,x,y,tool,toolOptions);if(!r.ok&&r.reason)toast(r.reason)}update()}
