$('city').addEventListener('pointerdown',e=>{if(session.screen!=='game'||document.querySelector('dialog[open]')||photo||e.button!==0)return;if(tool==='busline'){const p=view.getTile(e.clientX,e.clientY);if(!p)return;const i=p.y*48+p.x;if(session.world.tiles[i].type!=='road'){toast('Choose a stop on a road.');return;}if(busStops.includes(i)){if(i===busStops[0]&&busStops.length>=2)finishBusLine();else toast('That stop is already on this line.');return;}if(busStops.length>=12){toast('Finish this line before adding more stops.');return;}busStops.push(i);view.previewBusLine(busStops);$('toolHint').textContent=busStops.length+' stops planned · Click more roads or Finish bus line';return;}if(tool==='terrain'){const p=terrainPoint(e);if(!p)return;drag={terrain:true,id:e.pointerId,last:p,terrainChanges:new Map(),terrainGrounds:new Map(),terrainCost:0};$('city').setPointerCapture(e.pointerId);terrainStamp(p);return;}const p=['road','path'].includes(tool)?view.getRoadPoint(e.clientX,e.clientY):view.getTile(e.clientX,e.clientY);if(!p)return;if(isFacility()){painted.clear();paint(p);previewFacility(p);return;}if(['road','path'].includes(tool)&&roadMode==='curve'){curvePoints.push(p);if(curvePoints.length===3)commitRoad(curvePoints);else $('toolHint').textContent=curvePoints.length===1?'Click the bend point · Esc cancels':'Click the road endpoint · Esc cancels';return}if(toolOptions.zone&&zoneMode==='fill'){applyZone(E.fillZoneCells(session.world,p));return}drag={zone:!!toolOptions.zone&&zoneMode==='rectangle',id:e.pointerId,start:p,last:p,road:['road','path'].includes(tool)};painted.clear();$('city').setPointerCapture(e.pointerId);if(drag.zone)view.previewZones(E.rectangleCells(p,p),toolOptions.zone);else if(!drag.road)paint(p);else previewRoad([p,p]);});
$('city').addEventListener('pointermove',e=>{if(session.screen!=='game'||photo)return;if(tool==='busline')return;if(tool==='terrain'){const p=terrainPoint(e);view.hover(null);if(!p)return;view.showTerrainBrush(p.x,p.z,terrainRadius);if(drag?.terrain&&performance.now()-terrainStampTime>70){terrainStamp(p);drag.last=p;}return;}let p=['road','path'].includes(tool)?view.getRoadPoint(e.clientX,e.clientY):view.getTile(e.clientX,e.clientY);if(isFacility()){previewFacility(p);return;}view.hover(['road','path'].includes(tool)?null:p,tool==='bulldoze');if(!p)return;if(['road','path'].includes(tool)&&roadMode==='curve'&&curvePoints.length){previewRoad([...curvePoints,p]);return}if(!drag||drag.id!==e.pointerId)return;if(drag.terrain){finishTerrain();return;}if(drag.zone)view.previewZones(E.rectangleCells(drag.start,p),toolOptions.zone);else if(drag.road)previewRoad([drag.start,p]);else if(tool!=='inspect')for(let q of E.lineTiles(drag.last,p))paint(q);drag.last=p});
$('city').addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;if(drag.terrain){finishTerrain();return;}if(drag.zone){applyZone(E.rectangleCells(drag.start,view.getTile(e.clientX,e.clientY)||drag.last));view.clearLine()}else if(drag.road)commitRoad([drag.start,view.getRoadPoint(e.clientX,e.clientY)||drag.last]);drag=null;painted.clear()});
