$('pause').onclick=()=>{session.paused=!session.paused;update()};for(let n of [1,2,4])$('speed'+n).onclick=()=>{session.speed=n;session.paused=false;update()};$('center').onclick=()=>view.center();$('zoomIn').onclick=()=>view.zoom(.85);$('zoomOut').onclick=()=>view.zoom(1.18);$('night').onclick=()=>{view.setNight(!view.night);$('night').textContent=view.night?'☀':'☾'};$('infoToggle').onclick=()=>{$('infoPanel').hidden=!$('infoPanel').hidden};$('closeInfo').onclick=()=>{$('infoPanel').hidden=true};$('progressButton').onclick=()=>{$('infoPanel').hidden=!$('infoPanel').hidden};$('closeInspector').onclick=()=>{$('inspector').hidden=true};
