function pauseMenu(){if(session.screen!=='game')return;pausedBeforeMenu=session.paused;session.paused=true;view.running=false;$('pauseWorld').textContent=session.world.name+' · Day '+session.world.day;$('menuSaveStatus').textContent='Last verified save: '+timestamp(session.world.savedAt);$('pauseDialog').showModal()}
$('menu').onclick=pauseMenu;$('resume').onclick=()=>{$('pauseDialog').close();session.paused=pausedBeforeMenu;update()};$('save').onclick=()=>save();$('menuSave').onclick=()=>save();$('exitHome').onclick=exitHome;
function showWorlds(){if(session.screen==='game'&&!save(true))return;worldList();$('worldDialog').showModal();view.running=false}
function worldList(){const list=$('worldList');list.replaceChildren();if(!store.worlds.length){let p=document.createElement('p');p.className='muted';p.textContent='No saved cities yet. Start a new game.';list.append(p)}for(let w of [...store.worlds].sort((a,b)=>(b.savedAt||0)-(a.savedAt||0))){const a=E.analyze(w),card=document.createElement('div');card.className='world-card'+(selectedId===w.id?' selected':'');let icon=document.createElement('div');icon.className='world-icon';let info=document.createElement('div');info.className='world-info';let title=document.createElement('strong');title.textContent=w.name;let meta=document.createElement('small');meta.textContent=a.population.toLocaleString()+' residents · Day '+w.day+' · '+money(w.money);let stamp=document.createElement('small');stamp.textContent='Saved '+timestamp(w.savedAt);info.append(title,meta,stamp);let choose=document.createElement('button');choose.textContent='Play';choose.onclick=()=>start(w.id);card.onclick=e=>{if(e.target.tagName==='BUTTON')return;selectedId=w.id;worldList()};card.append(icon,info,choose);if(w.id!==session.world?.id){let del=document.createElement('button');del.className='delete-world';del.textContent='×';del.setAttribute('aria-label','Delete '+w.name);del.onclick=()=>{if(confirm('Permanently delete '+w.name+'? Export a backup first.'))try{store.remove(w.id);if(selectedId===w.id)selectedId=store.worlds[0]?.id;worldList()}catch(err){toast(err.message,true)}};card.append(del)}list.append(card)}}
$('continue').onclick=()=>start(store.currentId||store.worlds[0]?.id);$('loadGame').onclick=showWorlds;$('menuLoad').onclick=()=>{$('pauseDialog').close();showWorlds()};$('newGame').onclick=()=>{$('newDialog').showModal();$('newName').focus()};$('newWorld').onsubmit=e=>{e.preventDefault();if(session.screen==='game'&&!save(true))return;let terrain=document.querySelector('input[name=terrain]:checked').value;const w=E.createWorld($('newName').value,terrain);try{store.save(w);start(w.id);$('newName').value=''}catch(err){toast(err.message,true)}};
