$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3e6)throw Error('Backup is too large');const w=JSON.parse(await f.text());if(!E.valid(w))throw Error('Not a valid Borough world');if(session.screen==='game'&&!save(true))return;w.id=crypto.randomUUID();store.save(w);selectedId=w.id;worldList();toast('Backup imported as a separate city. Press Play to start it.')}catch(err){toast(err.message,true)}finally{e.target.value=''}};
function budgetDetails(){const w=session.world;if(!w)return;const a=E.analyze(w);$('taxValue').textContent=w.tax+'%';$('budgetDetails').innerHTML=[['Tax revenue',money(a.taxes)],['Service & road upkeep','−'+money(a.upkeep)],['Loan repayments','−'+money(a.repayment)],['Net daily balance',(a.income>=0?'+':'−')+money(Math.abs(a.income))],['Outstanding loans',money(w.loans)]].map(([k,v],i)=>`<div class="budget-row"><span>${k}</span><b class="${i===3?(a.income>=0?'positive':'negative'):''}">${v}</b></div>`).join('');$('loan').disabled=w.loans>0}
$('budget').onclick=()=>{$('tax').value=session.world.tax;budgetDetails();$('budgetDialog').showModal();view.running=false};$('tax').oninput=e=>{session.world.tax=Number(e.target.value);budgetDetails();update()};$('loan').onclick=()=>{if(session.world.loans>0)return;session.world.money+=10000;session.world.loans=12000;budgetDetails();update();toast('Loan received. ₡100 repaid every city day.')};$('homeSettings').onclick=()=>$('settingsDialog').showModal();$('gridSetting').onchange=()=>view.setBuild(tool!=='inspect'&&$('gridSetting').checked);$('quality').onchange=e=>{const quality=e.target.value,high=quality==='high',low=quality==='low';view.detailEnabled=!low;view.reflectionsEnabled=high;view.graphics.enabled=high;view.renderer.shadowMap.enabled=!low;view.renderer.setPixelRatio(high?Math.min(devicePixelRatio,1.25):1);view.graphics.resize();view.sun.castShadow=!low;view.renderer.shadowMap.needsUpdate=true;view.scene.traverse(o=>{if(o.material){for(let m of Array.isArray(o.material)?o.material:[o.material])m.needsUpdate=true}});if(view.world){view.refresh(true);view.landscape.refreshTrees(view.world)}try{localStorage.setItem('borough.graphics.v1',quality)}catch{}};$('help').onclick=()=>{$('helpDialog').showModal();view.running=false};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{b.closest('dialog').close();if(b.closest('dialog').id==='pauseDialog')session.paused=pausedBeforeMenu;update()});document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('close',()=>update());d.addEventListener('cancel',()=>{if(d.id==='pauseDialog')session.paused=pausedBeforeMenu})});
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save();return}if(e.key==='Escape'){if(curvePoints.length||drag){const terrainStroke=!!drag?.terrain;cancelRoad();$('toolHint').textContent=terrainStroke?'Terrain stroke finished · Undo is available':'Road cancelled · Select a start point';return}if(photo){photo=false;document.body.classList.remove('photo-mode');$('photoHint').hidden=true;view.setBuild(tool!=='inspect'&&$('gridSetting').checked);return}if(document.querySelector('dialog[open]'))return;if(session.screen==='game'){if(tool!=='inspect'||!$('buildPanel').hidden){closeBuild();view.clearLine();drag=null}else pauseMenu()}return}if(session.screen!=='game'||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();session.paused=!session.paused;update()}const k=e.key.toLowerCase();if(k==='r'&&isFacility()){e.preventDefault();toolOptions.rotation=((toolOptions.rotation||0)+1)%4;facilityHint();if(facilityHover)previewFacility(facilityHover);return;}if(['w','a','s','d'].includes(k)){e.preventDefault();view.pan(k==='a'?-7:k==='d'?7:0,k==='w'?-7:k==='s'?7:0)}if(e.key==='+'||e.key==='=')view.zoom(.9);if(e.key==='-')view.zoom(1.1)});
